class Student:
    def __init__(self, name, scores):
        self.name, self.scores = name, scores

    @property
    def average(self):
        return sum(self.scores) / len(self.scores)

    def __repr__(self):
        return f'Student({self.name!r}, avg={self.average:.1f})'

ece = Student('Ece', [90, 85])
ece.scores.append(70)
print(ece, ece.average)

text = 'Ece,90,85\nCan,70,x\nAli,60,75\nZeynep,95,100'

def parse(text):
    book, skipped = {}, []
    for line in text.splitlines():
        name, *raw_scores = line.split(',')
        for raw in raw_scores:
            try:
                book.setdefault(name, []).append(int(raw))
            except ValueError:
                skipped.append((name, raw))
    return book, skipped

print(parse(text))

