class GradeBook:
    def __init__(self):
        self.scores = {}

    def add(self, name, score):
        self.scores.setdefault(name, []).append(score)

    def average(self, name):
        s = self.scores.get(name, [])
        return sum(s) / len(s) if s else None

book = GradeBook()
for name, score in [('Ece', 90), ('Can', 70), ('Ece', 80), ('Can', 100)]:
    book.add(name, score)
print(book.average('Ece'), book.average('Can'), book.average('Ali'))

